"use client"

import React, { Fragment, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import Pageheader from '@/shared/layout-components/page-header/pageheader'
import Seo from '@/shared/layout-components/seo/seo'
import dynamic from 'next/dynamic'

const Select = dynamic(() => import('react-select'), { ssr: false })

type PlaylistItemType = 'video' | 'youtube' | 'quiz' | 'pdf'

type PlaylistItem = {
  id: string
  type: PlaylistItemType
  title: string
  source: string
  duration?: string
}

type ModuleFormData = {
  categoryId: string
  name: string
  coverImage: string
  shortDescription: string
  videos: number
  pdfs: number
  blogs: number
  quiz: number
  tests: number
  studentsEnrolled: number
  mentorIds: string[]
  playlist: PlaylistItem[]
}

const CATEGORY_OPTIONS = [
  { value: 'cat-1', label: 'Technical Skills' },
  { value: 'cat-2', label: 'Leadership & Soft Skills' },
  { value: 'cat-3', label: 'Product & Design' },
]

type MentorOption = {
  value: string
  label: string
  avatar: string
}

const MENTOR_OPTIONS: MentorOption[] = [
  { value: 'm1', label: 'Alex', avatar: '/assets/images/faces/2.jpg' },
  { value: 'm2', label: 'Sam', avatar: '/assets/images/faces/8.jpg' },
  { value: 'm3', label: 'Jordan', avatar: '/assets/images/faces/12.jpg' },
  { value: 'm4', label: 'Casey', avatar: '/assets/images/faces/10.jpg' },
  { value: 'm5', label: 'Morgan', avatar: '/assets/images/faces/5.jpg' },
  { value: 'm6', label: 'Riley', avatar: '/assets/images/faces/9.jpg' },
  { value: 'm7', label: 'Quinn', avatar: '/assets/images/faces/11.jpg' },
  { value: 'm8', label: 'Taylor', avatar: '/assets/images/faces/3.jpg' },
  { value: 'm9', label: 'Jamie', avatar: '/assets/images/faces/13.jpg' },
  { value: 'm10', label: 'Drew', avatar: '/assets/images/faces/6.jpg' },
]

const CreateModule = () => {
  const router = useRouter()
  const [activeTab, setActiveTab] = useState<'info' | 'playlist'>('info')
  const [formData, setFormData] = useState<ModuleFormData>({
    categoryId: '',
    name: '',
    coverImage: '',
    shortDescription: '',
    videos: 0,
    pdfs: 0,
    blogs: 0,
    quiz: 0,
    tests: 0,
    studentsEnrolled: 0,
    mentorIds: [],
    playlist: [],
  })

  const [coverImageFile, setCoverImageFile] = useState<File | null>(null)
  const [coverImagePreview, setCoverImagePreview] = useState<string>('')

  const handleInputChange = (field: keyof ModuleFormData, value: any) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }))
  }

  const handleCoverImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      setCoverImageFile(file)
      const reader = new FileReader()
      reader.onloadend = () => {
        setCoverImagePreview(reader.result as string)
        handleInputChange('coverImage', reader.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleCategoryChange = (option: { value: string; label: string } | null) => {
    handleInputChange('categoryId', option?.value || '')
  }

  const handleMentorsChange = (selectedOptions: any) => {
    const mentorIds = selectedOptions ? selectedOptions.map((opt: any) => opt.value) : []
    handleInputChange('mentorIds', mentorIds)
  }

  const handleAddPlaylistItem = () => {
    const newItem: PlaylistItem = {
      id: Date.now().toString(),
      type: 'video',
      title: '',
      source: '',
      duration: '',
    }
    handleInputChange('playlist', [...formData.playlist, newItem])
  }

  const handlePlaylistItemChange = (id: string, field: keyof PlaylistItem, value: any) => {
    handleInputChange(
      'playlist',
      formData.playlist.map((item) => (item.id === id ? { ...item, [field]: value } : item)),
    )
  }

  const handleRemovePlaylistItem = (id: string) => {
    handleInputChange(
      'playlist',
      formData.playlist.filter((item) => item.id !== id),
    )
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    // Here you would typically send the data to your API
    // For now, we'll just navigate back to the modules list
    console.log('Module data:', formData)
    router.push('/training/curriculum/modules')
  }

  const selectedMentors = MENTOR_OPTIONS.filter((m) => formData.mentorIds.includes(m.value))

  return (
    <Fragment>
      <Seo title="Create Training Module" />
      <Pageheader
        currentpage="Create Training Module"
        activepage="Training Curriculum"
        mainpage="Create Training Module"
      />
      <div className="grid grid-cols-12 gap-6">
        <div className="xl:col-span-12 col-span-12">
          <div className="box custom-box">
            <div className="box-header flex items-center justify-between flex-wrap gap-4">
              <div className="box-title">Create New Training Module</div>
              <Link
                href="/training/curriculum/modules"
                className="ti-btn ti-btn-light !py-1 !px-2 !text-[0.75rem]"
              >
                <i className="ri-arrow-left-line me-1" /> Back to Modules
              </Link>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="box-body">
                <div className="border-b border-gray-200 dark:border-defaultborder/10 mb-6">
                  <nav className="flex space-x-2 rtl:space-x-reverse" aria-label="Tabs" role="tablist">
                    <button
                      type="button"
                      onClick={() => setActiveTab('info')}
                      className={`hs-tab-active:bg-primary/10 hs-tab-active:text-primary hs-tab-active:border-primary -mb-px py-2 px-4 inline-flex items-center gap-2 text-sm font-medium text-center border-b-2 transition-colors ${
                        activeTab === 'info'
                          ? 'bg-primary/10 text-primary border-primary'
                          : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 border-transparent'
                      }`}
                      id="info-tab"
                      aria-controls="info-panel"
                    >
                      <i className="ri-file-text-line" />
                      Course Info
                    </button>
                    <button
                      type="button"
                      onClick={() => setActiveTab('playlist')}
                      className={`hs-tab-active:bg-primary/10 hs-tab-active:text-primary hs-tab-active:border-primary -mb-px py-2 px-4 inline-flex items-center gap-2 text-sm font-medium text-center border-b-2 transition-colors ${
                        activeTab === 'playlist'
                          ? 'bg-primary/10 text-primary border-primary'
                          : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 border-transparent'
                      }`}
                      id="playlist-tab"
                      aria-controls="playlist-panel"
                    >
                      <i className="ri-play-list-2-line" />
                      Playlist
                    </button>
                  </nav>
                </div>

                {activeTab === 'info' && (
                  <div id="info-panel" role="tabpanel" aria-labelledby="info-tab">
                    <div className="grid grid-cols-12 gap-4">
                      {/* Category Selection */}
                      <div className="xl:col-span-6 col-span-12">
                        <label htmlFor="category" className="form-label">
                          Category <span className="text-danger">*</span>
                        </label>
                        <Select
                          id="category"
                          value={CATEGORY_OPTIONS.find((opt) => opt.value === formData.categoryId) || null}
                          onChange={handleCategoryChange}
                          options={CATEGORY_OPTIONS}
                          classNamePrefix="Select2"
                          placeholder="Select Category"
                          menuPlacement="auto"
                        />
                      </div>

                      {/* Module Name */}
                      <div className="xl:col-span-6 col-span-12">
                        <label htmlFor="module-name" className="form-label">
                          Module Name <span className="text-danger">*</span>
                        </label>
                        <input
                          id="module-name"
                          type="text"
                          className="form-control"
                          placeholder="Enter module name"
                          value={formData.name}
                          onChange={(e) => handleInputChange('name', e.target.value)}
                          required
                        />
                      </div>

                      {/* Cover Image Upload */}
                      <div className="xl:col-span-12 col-span-12">
                        <label className="form-label">
                          Cover Image <span className="text-danger">*</span>
                        </label>
                        <div className="flex flex-col gap-3">
                          <input
                            type="file"
                            accept="image/*"
                            className="form-control"
                            onChange={handleCoverImageChange}
                          />
                          {coverImagePreview && (
                            <div className="mt-2">
                              <img
                                src={coverImagePreview}
                                alt="Cover preview"
                                className="w-full max-w-md h-48 object-cover rounded border border-defaultborder"
                              />
                            </div>
                          )}
                          {!coverImagePreview && formData.coverImage && (
                            <div className="mt-2">
                              <img
                                src={formData.coverImage}
                                alt="Cover preview"
                                className="w-full max-w-md h-48 object-cover rounded border border-defaultborder"
                              />
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Short Description */}
                      <div className="xl:col-span-12 col-span-12">
                        <label htmlFor="short-description" className="form-label">
                          Short Description <span className="text-danger">*</span>
                        </label>
                        <textarea
                          id="short-description"
                          className="form-control"
                          rows={4}
                          placeholder="Enter a brief description of the training module"
                          value={formData.shortDescription}
                          onChange={(e) => handleInputChange('shortDescription', e.target.value)}
                          required
                        />
                      </div>

                      {/* Summary Section */}
                      <div className="xl:col-span-12 col-span-12">
                        <div className="border-t border-defaultborder pt-4 mt-2">
                          <h5 className="font-semibold mb-4">Content Summary</h5>
                          <div className="grid grid-cols-12 gap-4">
                            <div className="xl:col-span-2 md:col-span-4 col-span-6">
                              <label htmlFor="videos" className="form-label">
                                Videos
                              </label>
                              <input
                                id="videos"
                                type="number"
                                className="form-control"
                                min="0"
                                value={formData.videos}
                                onChange={(e) =>
                                  handleInputChange('videos', parseInt(e.target.value, 10) || 0)
                                }
                              />
                            </div>
                            <div className="xl:col-span-2 md:col-span-4 col-span-6">
                              <label htmlFor="pdfs" className="form-label">
                                PDFs
                              </label>
                              <input
                                id="pdfs"
                                type="number"
                                className="form-control"
                                min="0"
                                value={formData.pdfs}
                                onChange={(e) =>
                                  handleInputChange('pdfs', parseInt(e.target.value, 10) || 0)
                                }
                              />
                            </div>
                            <div className="xl:col-span-2 md:col-span-4 col-span-6">
                              <label htmlFor="blogs" className="form-label">
                                Blogs
                              </label>
                              <input
                                id="blogs"
                                type="number"
                                className="form-control"
                                min="0"
                                value={formData.blogs}
                                onChange={(e) =>
                                  handleInputChange('blogs', parseInt(e.target.value, 10) || 0)
                                }
                              />
                            </div>
                            <div className="xl:col-span-2 md:col-span-4 col-span-6">
                              <label htmlFor="quiz" className="form-label">
                                Quiz
                              </label>
                              <input
                                id="quiz"
                                type="number"
                                className="form-control"
                                min="0"
                                value={formData.quiz}
                                onChange={(e) =>
                                  handleInputChange('quiz', parseInt(e.target.value, 10) || 0)
                                }
                              />
                            </div>
                            <div className="xl:col-span-2 md:col-span-4 col-span-6">
                              <label htmlFor="tests" className="form-label">
                                Tests
                              </label>
                              <input
                                id="tests"
                                type="number"
                                className="form-control"
                                min="0"
                                value={formData.tests}
                                onChange={(e) =>
                                  handleInputChange('tests', parseInt(e.target.value, 10) || 0)
                                }
                              />
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Students Enrolled */}
                      <div className="xl:col-span-6 col-span-12">
                        <label htmlFor="students-enrolled" className="form-label">
                          Students Enrolled
                        </label>
                        <input
                          id="students-enrolled"
                          type="number"
                          className="form-control"
                          min="0"
                          placeholder="0"
                          value={formData.studentsEnrolled}
                          onChange={(e) =>
                            handleInputChange(
                              'studentsEnrolled',
                              parseInt(e.target.value, 10) || 0,
                            )
                          }
                        />
                      </div>

                      {/* Mentors Assigned */}
                      <div className="xl:col-span-6 col-span-12">
                        <label className="form-label">Mentors Assigned</label>
                        <Select
                          isMulti
                          value={selectedMentors}
                          onChange={handleMentorsChange}
                          options={MENTOR_OPTIONS}
                          classNamePrefix="Select2"
                          placeholder="Select mentors"
                          menuPlacement="auto"
                          formatOptionLabel={(option: MentorOption) => (
                            <div className="flex items-center gap-2">
                              <img
                                src={option.avatar}
                                alt={option.label}
                                className="w-6 h-6 rounded-full"
                              />
                              <span>{option.label}</span>
                            </div>
                          )}
                        />
                      </div>
                    </div>
                  </div>
                )}

                {activeTab === 'playlist' && (
                  <div id="playlist-panel" role="tabpanel" aria-labelledby="playlist-tab">
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <h5 className="font-semibold mb-1">Course Playlist</h5>
                        <p className="text-[#8c9097] dark:text-white/50 text-[0.8125rem] mb-0">
                          Add items like uploaded videos, YouTube links, quizzes, PDFs, etc. The
                          order here will be used as the course flow.
                        </p>
                      </div>
                      <button
                        type="button"
                        className="ti-btn ti-btn-primary-full !mb-0"
                        onClick={handleAddPlaylistItem}
                      >
                        <i className="ri-add-line me-1 align-middle" />
                        Add Item
                      </button>
                    </div>

                    {formData.playlist.length === 0 && (
                      <div className="border border-dashed border-defaultborder rounded-md p-4 text-center text-[#8c9097] dark:text-white/50 text-[0.8125rem]">
                        No playlist items yet. Click{' '}
                        <span className="font-semibold">Add Item</span> to start building the
                        course.
                      </div>
                    )}

                    <div className="space-y-4">
                      {formData.playlist.map((item, index) => (
                        <div
                          key={item.id}
                          className="border border-defaultborder rounded-md p-4 bg-white/60 dark:bg-black/20"
                        >
                          <div className="flex items-center justify-between mb-3">
                            <div className="flex items-center gap-2">
                              <span className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-[0.75rem]">
                                {index + 1}
                              </span>
                              <span className="font-semibold text-[0.875rem]">
                                {item.title || `Playlist item ${index + 1}`}
                              </span>
                            </div>
                            <button
                              type="button"
                              className="ti-btn ti-btn-light !py-1 !px-2 !text-[0.75rem]"
                              onClick={() => handleRemovePlaylistItem(item.id)}
                            >
                              <i className="ri-delete-bin-line me-1 align-middle" />
                              Remove
                            </button>
                          </div>

                          <div className="grid grid-cols-12 gap-4">
                            <div className="xl:col-span-3 md:col-span-4 col-span-12">
                              <label
                                className="form-label"
                                htmlFor={`playlist-type-${item.id}`}
                              >
                                Content Type
                              </label>
                              <select
                                id={`playlist-type-${item.id}`}
                                className="form-control"
                                value={item.type}
                                onChange={(e) =>
                                  handlePlaylistItemChange(
                                    item.id,
                                    'type',
                                    e.target.value as PlaylistItemType,
                                  )
                                }
                              >
                                <option value="video">Uploaded Video</option>
                                <option value="youtube">YouTube Link</option>
                                <option value="quiz">Quiz</option>
                                <option value="pdf">PDF / Document</option>
                              </select>
                            </div>

                            <div className="xl:col-span-4 md:col-span-8 col-span-12">
                              <label
                                className="form-label"
                                htmlFor={`playlist-title-${item.id}`}
                              >
                                Title
                              </label>
                              <input
                                id={`playlist-title-${item.id}`}
                                type="text"
                                className="form-control"
                                placeholder="Lesson title"
                                value={item.title}
                                onChange={(e) =>
                                  handlePlaylistItemChange(item.id, 'title', e.target.value)
                                }
                              />
                            </div>

                            <div className="xl:col-span-3 md:col-span-6 col-span-12">
                              <label
                                className="form-label"
                                htmlFor={`playlist-source-${item.id}`}
                              >
                                {item.type === 'youtube'
                                  ? 'YouTube URL'
                                  : item.type === 'quiz'
                                  ? 'Quiz Id / Link'
                                  : item.type === 'pdf'
                                  ? 'File URL'
                                  : 'Video URL'}
                              </label>
                              <input
                                id={`playlist-source-${item.id}`}
                                type="text"
                                className="form-control"
                                placeholder={
                                  item.type === 'youtube'
                                    ? 'https://youtube.com/...'
                                    : item.type === 'quiz'
                                    ? 'Quiz reference'
                                    : 'Resource URL or path'
                                }
                                value={item.source}
                                onChange={(e) =>
                                  handlePlaylistItemChange(item.id, 'source', e.target.value)
                                }
                              />
                            </div>

                            <div className="xl:col-span-2 md:col-span-6 col-span-12">
                              <label
                                className="form-label"
                                htmlFor={`playlist-duration-${item.id}`}
                              >
                                Duration (min)
                              </label>
                              <input
                                id={`playlist-duration-${item.id}`}
                                type="text"
                                className="form-control"
                                placeholder="e.g. 10"
                                value={item.duration || ''}
                                onChange={(e) =>
                                  handlePlaylistItemChange(item.id, 'duration', e.target.value)
                                }
                              />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
              <div className="box-footer flex justify-end gap-2 pt-4 border-t border-defaultborder">
                <Link
                  href="/training/curriculum/modules"
                  className="ti-btn ti-btn-light"
                >
                  Cancel
                </Link>
                <button
                  type="submit"
                  className="ti-btn ti-btn-primary-full"
                >
                  Create Module
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </Fragment>
  )
}

export default CreateModule
